                    if (!GetClientRect(hwnd, &client) ||
                        client.right <= client.left || client.bottom <= client.top) {
                        Sleep(30);
                        continue;
                    }
                    if (state.resized) { state.resized = false; resetNeeded = true; }
                    if (resetNeeded) {
                        hr = device->TestCooperativeLevel();
